pushParticlesApart(numIters) {
  const n = this.numParticles, pos = this.pos;
  const pInv = this.pInvSpacing, pNumX = this.pNumX, pNumY = this.pNumY, pNumCells = this.pNumCells;
  const counts = this.numCellParticles, firstId = this.firstCellParticle, ids = this.cellParticleIds;

  // count-sort particles into a hash grid
  counts.fill(0);
  for (let i = 0; i < n; i++) {
    const xi = clamp(Math.floor(pos[2*i]   * pInv), 0, pNumX - 1);
    const yi = clamp(Math.floor(pos[2*i+1] * pInv), 0, pNumY - 1);
    counts[xi * pNumY + yi]++;
  }
  let first = 0;
  for (let i = 0; i < pNumCells; i++) { first += counts[i]; firstId[i] = first; }
  firstId[pNumCells] = first;
  for (let i = 0; i < n; i++) {
    const xi = clamp(Math.floor(pos[2*i]   * pInv), 0, pNumX - 1);
    const yi = clamp(Math.floor(pos[2*i+1] * pInv), 0, pNumY - 1);
    ids[--firstId[xi * pNumY + yi]] = i;
  }

  const minDist = 2 * this.particleRadius, minDist2 = minDist * minDist;
  for (let iter = 0; iter < numIters; iter++) {
    for (let i = 0; i < n; i++) {
      const px = pos[2*i], py = pos[2*i+1];
      const pxi = clamp(Math.floor(px * pInv), 0, pNumX - 1);
      const pyi = clamp(Math.floor(py * pInv), 0, pNumY - 1);
      const x0 = pxi > 0 ? pxi - 1 : 0, x1 = pxi < pNumX - 1 ? pxi + 1 : pxi;
      const y0 = pyi > 0 ? pyi - 1 : 0, y1 = pyi < pNumY - 1 ? pyi + 1 : pyi;
      for (let xi = x0; xi <= x1; xi++) {
        const base = xi * pNumY;
        for (let yi = y0; yi <= y1; yi++) {
          const cell = base + yi;
          const a = firstId[cell], b = firstId[cell + 1];
          for (let k = a; k < b; k++) {
            const id = ids[k];
            if (id <= i) continue;       // each pair resolved once, symmetrically
            let dx = pos[2*id] - px, dy = pos[2*id+1] - py;
            const d2 = dx*dx + dy*dy;
            if (d2 > minDist2 || d2 === 0) continue;
            const d = Math.sqrt(d2), sc = 0.5 * (minDist - d) / d;
            dx *= sc; dy *= sc;
            pos[2*i]   -= dx; pos[2*i+1]  -= dy;
            pos[2*id]  += dx; pos[2*id+1] += dy;
          }
        }
